+    assert!(n[0].starts_with("Quadro") && n[1].starts_with("Quadro"), "{n:?}");
+    assert!(n[2].starts_with("Intel") && n[3].starts_with("Intel"), "{n:?}");
+    assert!(n[4].starts_with("Microsoft"), "{n:?}");
